package com.prospr.repository; import java.time.*; import java.util.*; import org.springframework.data.mongodb.repository.MongoRepository; import com.prospr.model.TransactionEntry; public interface TransactionRepository extends MongoRepository<TransactionEntry,String>{ List<TransactionEntry> findByOwnerIdAndDateBetweenAndExcludedFalse(String ownerId, LocalDate from, LocalDate to); List<TransactionEntry> findByOwnerIdOrderByDateDesc(String ownerId); List<TransactionEntry> findByHouseholdIdAndDateBetweenAndExcludedFalse(String householdId, LocalDate from, LocalDate to); List<TransactionEntry> findByHouseholdIdOrderByDateDesc(String householdId); }
